/**
 * `DeepSeekAdapter`: fetch + SSE against a DeepSeek (OpenAI-compatible)
 * chat-completions endpoint, emitting harness StreamChunks. The adapter is
 * transport-only: connection facts arrive through a thunk resolved once per
 * operation and the bearer token through a per-request resolver, so the
 * registering plugin owns validation, layering, and credential policy.
 *
 * @module dsh-llm-deepseek/adapter
 */

import { attributionHeaders, CONTEXT_WINDOW_EXCEEDED_CODE, isContextWindowExceededError, isQuotaExceededError, LlmAdapter, LlmError, ProviderRequestId, QUOTA_EXCEEDED_CODE, ReasoningEffortId } from '@deepseek-ai/dsh-llm'
import type {
  GenerateOptions,
  LlmModelInfo,
  LlmProviderInfo,
  LlmResolvedModelInfo,
  ResolvedRetryPolicy,
  StreamChunk,
} from '@deepseek-ai/dsh-llm'
import type { CredentialRef } from '@deepseek-ai/dsh-credentials'
import { idleWatchdog, timeoutOf } from '@deepseek-ai/dsh-timeout'
import type { AnonymousUserId } from '@deepseek-ai/dsh-anonymous-user-id'
import { serializeRequest } from './serialize.ts'
import type { RequestDefaults } from './serialize.ts'
import { parseSse } from './sse.ts'
import { translate } from './translate.ts'
import type { WireError } from './types.ts'

/** One optional model entry advertised by the direct-fetch adapter. */
export interface DeepSeekCatalogModel {
  /** Wire model id accepted by the configured endpoint. */
  id: string
  /** Selector label; defaults to {@link id}. */
  name?: string
  /** Optional selector detail for deployments with similar model variants. */
  description?: string
  /** Known combined request/response context capacity; omitted when deployment metadata is unavailable. */
  contextWindow?: number
  /** Per-request output cap for this model; omission falls back to the profile's {@link DeepSeekConnectionOptions.maxTokens}. */
  maxTokens?: number
}

/**
 * Validated connection facts for one operation. The plugin's
 * `resolveAdapterOptions` is the one explicit resolve step producing this
 * shape; the adapter trusts it and re-reads it per operation, which is what
 * makes a configuration change reach the next request without re-registration.
 */
export interface DeepSeekConnectionOptions {
  /** Endpoint base; `/chat/completions` is appended. */
  baseURL: string
  /**
   * Credential reference of this same resolution, resolved per request.
   * Travelling with the endpoint is the point: a request can never pair one
   * generation's URL with another generation's secret. Configuration carries
   * only this name — a literal key is not a configuration value.
   */
  apiKeyEnv: CredentialRef
  /** Request defaults applied to every call (thinking mode, effort). */
  defaults: RequestDefaults
  /** Default per-request output cap; explicit request values win. */
  maxTokens: number
  /** Positive context capacity used when the selected model has no exact value. */
  defaultContextWindow: number
  /** Advisory models exposed to discovery consumers; requests remain unrestricted. */
  models: readonly DeepSeekCatalogModel[]
  /** Maximum provider idle time while one stream read is outstanding. */
  streamIdleTimeoutMs: number
  /** Provider-owned model-request retry policy, already resolved. */
  retryPolicy: ResolvedRetryPolicy
}

/** Constructor options for {@link DeepSeekAdapter}: the operation-local resolution hooks the plugin owns. */
export interface DeepSeekAdapterOptions {
  /** Current validated connection facts; called once per operation. */
  options: () => DeepSeekConnectionOptions
  /**
   * Resolve the bearer token for the connection facts of one request. The
   * snapshot is passed in — never re-read — so the key can only ever come
   * from the same resolution as the endpoint it is sent to. Throws `LlmError`
   * `MISSING_CREDENTIAL` when no key is available anywhere.
   */
  resolveApiKey: (connection: DeepSeekConnectionOptions) => Promise<string>
  /** Resolve the harness-home anonymous id shared with telemetry and feedback. */
  resolveUserId: () => AnonymousUserId
}

/** Default maximum idle interval while an adapter stream read is outstanding. */
export const DEFAULT_STREAM_IDLE_TIMEOUT_MS = 300_000
/** Default combined request/response context capacity. */
export const DEFAULT_CONTEXT_WINDOW = 1_000_000
/** Default per-request output-token cap. */
export const DEFAULT_MAX_TOKENS = 256_000
const STREAM_IDLE_TIMEOUT_CODE = 'LLM_STREAM_IDLE_TIMEOUT'
const OFF_REASONING_EFFORT = ReasoningEffortId('off')
const HIGH_REASONING_EFFORT = ReasoningEffortId('high')
const MAX_REASONING_EFFORT = ReasoningEffortId('max')
const REASONING_EFFORTS = [
  { id: OFF_REASONING_EFFORT, name: 'Off' },
  { id: HIGH_REASONING_EFFORT, name: 'High' },
  { id: MAX_REASONING_EFFORT, name: 'Max' },
] as const
const OFF_ONLY_REASONING_EFFORTS = [
  { id: OFF_REASONING_EFFORT, name: 'Off' },
] as const

function modelInfo(provider: string, model: DeepSeekCatalogModel): LlmModelInfo {
  return {
    provider,
    id: model.id,
    name: model.name ?? model.id,
    ...model.description === undefined ? {} : { description: model.description },
    inputModalities: ['text'],
  }
}

function providerRetryAfterMs(value: string | null): number | undefined {
  if (value === null) return undefined
  if (/^\d+$/.test(value)) {
    const delay = Number(value) * 1_000

   * indexes, and fold the paired comparison. The arms run as one paired fleet
   * run whose cells alternate, so neither arm is confounded with the hour it
   * ran in. Every refusal happens before the first cell runs; a cell the fleet
   * kept as an error leaves its repetition unpaired instead of failing the
   * experiment.
   * @param plan - environments, repetitions, the two arms with their model
   *   routes and optional attempt ladders and implementers, the workspace root,
   *   and an optional policy version, base seed, frozen digest, abort signal,
   *   and result sink.
   * @returns the digest, both arms with their ladders and stamp groups, one
   *   cell per environment, every cell an arm kept as an error, the pooled
   *   delta with its interval, the spend, the caps both arms ran under, and
   *   the verdict.
   * @throws {@link ExperimentError} for a plan that names no or a duplicate or
   *   unregistered environment, asks for no repetition, sets a seed that is not
   *   a safe non-negative integer, carries an arm ladder with no rung or one
   *   whose first rung names another route, whose two arms would run under
   *   different caps, declares a digest its content does not freeze to, or
   *   projects more tokens than the budget.
   * @throws {@link EnvironmentRunError} unchanged from
   *   {@link EnvironmentRunner.checkImplementer}, when either arm names an
   *   implementer provider this composition cannot honor.
   */
  async run(plan: ExperimentPlan): Promise<ExperimentResult> {
    const { digest, caps } = this.freeze(plan)
    const arms: ExperimentArms = {
      baseline: resolveArm(plan.baseline, digest, 'baseline'),
      candidate: resolveArm(plan.candidate, digest, 'candidate'),
    }
    const [baseline, candidate] = await this.ctx.fleet.runPaired(armPlan(plan, arms.baseline), armPlan(plan, arms.candidate))
    const result = foldExperiment({
      digest,
      arms,
      environments: plan.environments,
      repetitions: plan.repetitions,
      thresholds: this.resolved.thresholds,
      caps,
      baseline,
      candidate,
    })
    await record(result, plan.sink)
    return result
  }

  /**
   * Validate the plan and both arms' implementers, resolve the caps both arms
   * run under, compute the digest over them, and check the projection against
   * the budget.
   */
  private freeze(plan: ExperimentPlan): { digest: string; caps: readonly BudgetCap[] } {
    if (!Number.isInteger(plan.repetitions) || plan.repetitions < 1) {
      throw new ExperimentError(`repetitions must be a positive integer, got ${String(plan.repetitions)}`, 'EXPERIMENT_INVALID_PLAN')
    }
    if (plan.seed !== undefined && !isSeed(plan.seed)) {
      throw new ExperimentError(`seed must be a non-negative integer, got ${String(plan.seed)}`, 'EXPERIMENT_INVALID_PLAN')
    }
    if (plan.environments.length === 0) throw new ExperimentError('the plan names no environment', 'EXPERIMENT_INVALID_PLAN')
    for (const role of EXPERIMENT_ARM_ROLES) {
      const arm = plan[role]
      if (arm.ladder?.length === 0) {
        throw new ExperimentError(`the ${role} arm's attempt ladder names no rung`, 'EXPERIMENT_INVALID_PLAN')
      }
      if (ladderConflicts(arm)) {
        const first = arm.ladder?.[0]?.model as EnvironmentRunModel
        throw new ExperimentError(`the ${role} arm runs ${arm.provider}/${arm.model} but its first ladder rung names ${first.provider}/${first.model}, so its first attempt would not be the arm it is published under`, 'EXPERIMENT_LADDER_CONFLICT')
      }
      // Both arms are checked here, so an implementer this composition cannot
      // honor refuses the plan rather than failing every cell of the arm that
      // names it — which, for a candidate arm, would spend the baseline arm in
      // full first and then fold to `inconclusive` with nothing paired. The
      // arm's own route is the stamped one: a first rung naming another route
      // was refused above.
      this.ctx.environmentRuns.checkImplementer(armImplementer(arm), { provider: arm.provider, model: arm.model })
    }
    const named = new Set<EnvironmentId>()
    for (const environment of plan.environments) {
      if (named.has(environment)) throw new ExperimentError(`environment "${environment}" is named twice`, 'EXPERIMENT_INVALID_PLAN')
      if (this.ctx.environments.get(environment) === undefined) {
        throw new ExperimentError(`environment "${environment}" is not registered`, 'EXPERIMENT_INVALID_PLAN')
      }
      named.add(environment)
    }
    const caps = this.agreedCaps(plan)
    const digest = planDigest(plan, this.resolved.thresholds, caps)
    if (plan.digest !== undefined && plan.digest !== digest) {
      throw new ExperimentError(`the plan declares digest ${plan.digest} but freezes to ${digest}`, 'EXPERIMENT_PLAN_NOT_FROZEN')
    }
    const projected = projectedTokens(plan, this.resolved.thresholds.cellTokenCap)
    if (projected > this.resolved.tokenBudget) {
      throw new ExperimentError(`the plan projects ${projected} tokens over a budget of ${this.resolved.tokenBudget}`, 'EXPERIMENT_OVER_BUDGET')
    }
    return { digest, caps }
  }

  /**
   * The caps both arms run their cells under. A comparison whose arms stop at
   * different ceilings measures the ceilings as much as the arms, so the plan is
   * refused before either arm starts rather than reported with a caveat.
   * @param plan - the frozen plan, supplying the implementer of each arm.
   * @returns the caps every cell of both arms runs under, in cap evaluation order.
   * @throws {@link ExperimentError} when the two arms resolve to different caps.
   */
  private agreedCaps(plan: ExperimentPlan): readonly BudgetCap[] {
    const baseline = this.ctx.environmentRuns.cellCaps(armImplementer(plan.baseline))
    const candidate = this.ctx.environmentRuns.cellCaps(armImplementer(plan.candidate))
    if (!capsAgree(baseline, candidate)) {
      throw new ExperimentError(`the arms would run under different caps — baseline ${describeCaps(baseline)}, candidate ${describeCaps(candidate)} — so their cells would not be comparable`, 'EXPERIMENT_UNEQUAL_CAPS')
    }
    return baseline
  }
}

export class PiAiAdapter extends LlmAdapter {
  private snapshot: PiAiSnapshot | undefined

  constructor(private readonly config: PiAiAdapterOptions) {
    super()
  }

  /**
   * The snapshot for the current profiles. Resolution memoizes its result, so
   * an unchanged configuration is recognized by identity; a changed one gets a
   * brand-new collection, leaving any snapshot an operation already captured
   * untouched for as long as that operation holds it.
   */
  private current(): PiAiSnapshot {
    const profiles = this.config.profiles()
    if (this.snapshot?.profiles === profiles) return this.snapshot
    const models: MutableModels = createModels()
    for (const profile of profiles.values()) models.setProvider(profile.piProvider)
    this.snapshot = { profiles, models }
    return this.snapshot
  }

  /** The profile for one route within one snapshot, or the not-owned failure. */
  private profileOf(snapshot: PiAiSnapshot, provider: string): ResolvedPiAiProviderProfile {
    const profile = snapshot.profiles.get(provider)
    if (profile === undefined) {
      throw new LlmError(`pi-ai adapter does not own provider "${provider}"`, 'NO_ADAPTER')
    }
    return profile
  }

  /** The configured descriptor for one exact route/model pair within one snapshot. */
  private modelOf(snapshot: PiAiSnapshot, provider: string, model: string): Model<Api> {
    this.profileOf(snapshot, provider)
    const resolved = snapshot.models.getModel(provider, model)
    if (resolved === undefined) {
      throw new LlmError(`pi-ai provider "${provider}" has no configured model "${model}"`, 'UNKNOWN_MODEL')
    }
    return resolved
  }

  override providerInfo(provider: string): LlmProviderInfo {
    // The configured name, not the route key: `displayName` exists so a
    // deployment can label a route, and a label only the configuration surface
    // reads would leave every selector showing the raw key.
    return { id: provider, name: this.current().profiles.get(provider)?.displayName ?? provider }
  }

  override providerRetryPolicy(provider: string): ResolvedRetryPolicy | undefined {
    return this.current().profiles.get(provider)?.retryPolicy
  }

  override listModels(provider: string): Promise<readonly LlmModelInfo[]> {
    return Promise.resolve().then(() => {
      const snapshot = this.current()
      this.profileOf(snapshot, provider)
      return snapshot.models.getModels(provider).map(model => ({
        provider,
        id: model.id,
        name: model.name,
        inputModalities: [...model.input],
      }))
    })
  }

  override resolveModel(
    provider: string,
    model: string,
    _signal?: AbortSignal,
  ): Promise<LlmResolvedModelInfo> {
    return Promise.resolve().then(() => {
      const snapshot = this.current()
      const profile = this.profileOf(snapshot, provider)
      const resolvedModel = this.modelOf(snapshot, provider, model)
      const defaultLevel = describableReasoningLevel(resolvedModel, profile.reasoning)
      // Only a cap the deployment configured is a request default; the
      // catalog's `maxTokens` sizes the model and stops there.
      const configuredMaxTokens = profile.configuredMaxTokens.get(model)
      return {
        provider,
        id: model,
        name: resolvedModel.name,
        inputModalities: [...resolvedModel.input],
        context: { contextWindow: resolvedModel.contextWindow },
        ...configuredMaxTokens === undefined ? {} : { defaultMaxTokens: configuredMaxTokens },
        ...reasoningInfo(resolvedModel, defaultLevel),
      }
    })
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    if (options.stop !== undefined) {
      throw new LlmError('llm-pi-ai does not support GenerateOptions.stop', 'UNSUPPORTED_OPTION')
    }
    // One capture per stream call, taken before any await: the profile, the
    // model descriptor, and the collection all come from the same immutable
    // snapshot, and the credential freezes with them. A configuration change
    // mid-request builds a separate snapshot, so this request finishes under
    // the one it started with and the next call picks up the new one.
    const snapshot = this.current()
    const profile = this.profileOf(snapshot, options.provider)
    const model = this.modelOf(snapshot, options.provider, options.model)
    const reasoning = resolveReasoningLevel(
      model,
      options.reasoningEffort ?? profile.reasoning,
    )
    const apiKey = await this.config.resolveApiKey(options.provider, profile)

    const consumer = new AbortController()
    const upstream = options.signal === undefined
      ? consumer.signal
      : AbortSignal.any([options.signal, consumer.signal])
    const streamIdleTimeoutMs = profile.streamIdleTimeoutMs
