/**
 * Validate a plan, resolve its environment selection, enumerate the cells it
 * runs, and open the ledger they fold into. Every refusal a plan earns
 * happens here, before any cell of it — or of a plan paired with it — starts.
 */
private async prepare(plan: FleetPlan): Promise<PlanRun> {
  if (!Number.isInteger(plan.repetitions) || plan.repetitions < 1) {
    throw new FleetError(`repetitions must be a positive integer, got ${String(plan.repetitions)}`, 'FLEET_INVALID_PLAN')
  }
  if (plan.tokenCeiling !== undefined && (!Number.isInteger(plan.tokenCeiling) || plan.tokenCeiling < 1)) {
    throw new FleetError(`tokenCeiling must be a positive integer, got ${String(plan.tokenCeiling)}`, 'FLEET_INVALID_PLAN')
  }

  }
}

class StubDefaultModel extends Service {
  constructor(ctx: Context) {
    super(ctx, 'agentDefaultModel')
  }
  currentSelection() {
    return DEFAULT_MODEL
  }
}

type Script = (request: EnvironmentRunRequest) => EnvironmentRunReport | Promise<EnvironmentRunReport>

class StubRuns extends Service {
  static current: StubRuns
  readonly requests: EnvironmentRunRequest[] = []
  /** Every implementer preflight the fleet ran, with the route it stamped. */
  readonly checked: { implementer: EnvironmentRunImplementer; model: EnvironmentRunModel }[] = []
  /** Providers this composition holds; a subagent implementer naming another is refused. */
  providers = new Set<string>()
  script: Script = request => report(request, { certified: true })
  inFlight = 0
  maxInFlight = 0
  constructor(ctx: Context) {
    super(ctx, 'environmentRuns')
    StubRuns.current = this
  }
  checkImplementer(implementer: EnvironmentRunImplementer, model: EnvironmentRunModel): void {
    this.checked.push({ implementer, model })
    if (implementer.kind === 'route' || this.providers.has(implementer.provider)) return
    throw new EnvironmentRunError(
      `implementer provider "${implementer.provider}" is unavailable: no subagent provider is registered under that name`,
      'ENVIRONMENT_RUN_IMPLEMENTER_UNAVAILABLE',
    )
  }
  async run(request: EnvironmentRunRequest): Promise<EnvironmentRunReport> {
    this.requests.push(request)
    this.inFlight += 1
    this.maxInFlight = Math.max(this.maxInFlight, this.inFlight)
    try {
      return await this.script(request)
    } finally {
      this.inFlight -= 1
    }
  }
}

interface ReportShape {
  certified: boolean
  attempts?: number
  usage?: { inputTokens: number; outputTokens: number }
  /** Omit the stamp's implementer, as a log written before the field existed states it. */
  unstampedImplementer?: boolean
}

/** The rungs a laddered request resolves to, or `undefined` for a request that named none. */
function ladderOf(request: EnvironmentRunRequest, model: EnvironmentRunModel): EnvironmentRunStampRung[] | undefined {
  return request.ladder?.map(rung => ({
    ...rung.model ?? model,
    ...rung.share === undefined ? {} : { share: rung.share },
  }))
}

/** The route one stamped rung names, without the budget share recorded beside it. */
function routeOf(rung: EnvironmentRunStampRung): EnvironmentRunModel {
  return { provider: rung.provider, model: rung.model }
}

function report(request: EnvironmentRunRequest, shape: ReportShape): EnvironmentRunReport {
  const model = request.model ?? DEFAULT_MODEL
  const count = shape.attempts ?? 1
  const ladder = ladderOf(request, model)
  const first = ladder?.[0]
  const attempts = Array.from({ length: count }, (_, index) => ({
    attempt: index + 1,
    model: ladder?.[index] === undefined ? model : routeOf(ladder[index]),
    transcript: request.implementer?.kind === 'subagent' ? 'dropped' as const : 'kept' as const,
    results: [{
      checkId: CheckId('check'),
      status: shape.certified && index === count - 1 ? 'pass' as const : 'fail' as const,
      evidence: 'exit 0',
    }],
    treeHash: HEX,
  }))
  return {
    environment: request.environment,
    sessionId: SessionId(`session-${request.environment}-${request.repetition ?? 0}-${model.model}`),
    stamp: {
      kind: 'environment/run',
      version: 1,
      environmentId: request.environment,
      environmentKind: 'smoke',
      heldOut: request.environment === RESERVED,
      promptSha256: HEX,
      checksSha256: HEX,
      contentSha256: HEX,
      repetition: request.repetition ?? 0,
      ...request.group === undefined ? {} : { group: request.group },
      model: first === undefined ? model : routeOf(first),
      ...ladder === undefined ? {} : { ladder },
      isolation: 'process',
      ...shape.unstampedImplementer === true
        ? {}
        : { implementer: request.implementer?.kind === 'subagent' ? request.implementer.provider : 'route' },
    },
    attempts,
    certified: shape.certified,
    ...shape.usage === undefined ? {} : { usage: shape.usage },
    caps: [],
    escapesDenied: 0,
  }
}

function row(overrides: Partial<LeaderboardRow> & Pick<LeaderboardRow, 'model' | 'environmentId'>): LeaderboardRow {
  return {
    provider: 'mock',
    environmentKind: 'smoke',
    heldOut: false,
    isolation: 'process',
    implementer: 'route',
    runs: 2,
    errors: 0,
    certified: 2,
    certificateRate: 1,
    attemptsMean: 1,
    inputTokens: 0,
    outputTokens: 0,
    ...overrides,
  }
}

